def answer(query, can_verify_via_tool, is_well_established_fact):
    """Simplified illustration of tool use + refusal calibration
    changing what a model does with an uncertain claim."""
    if can_verify_via_tool:
        return web_search_or_db_lookup(query)   # ground the answer externally

    if is_well_established_fact:
        return generate_from_memory(query)      # safe to answer directly

    # No way to verify, and not a well-known fact - decline instead of guessing
    return "I can't verify this without a reliable source."

def total_tokens_per_query(base_tokens, reasoning_multiplier):
    # reasoning models emit far more tokens per answer: roughly 10x-100x more
    return base_tokens * reasoning_multiplier

base = 500  # tokens for a short, non-reasoning answer
for multiplier in (1, 10, 100):
    tokens = total_tokens_per_query(base, multiplier)
    print(f"{multiplier:>3}x reasoning -> {tokens:,} tokens/query")

